import json,statistics,csv,hashlib,argparse
from pathlib import Path
ap=argparse.ArgumentParser();ap.add_argument('--receipt',required=True);ap.add_argument('--out',required=True);args=ap.parse_args();raw=Path(args.receipt);x=json.loads(raw.read_bytes());results=x['results'];old=[r['native_push_and_finish_seconds'] for r in results if r['algorithm']=='ORIGINAL'];new=[r['native_push_and_finish_seconds'] for r in results if r['algorithm']=='ROLLING'];a=(min(old)+max(old))/2;b=(min(new)+max(new))/2;assert abs(a-x['original_native_median_seconds'])<1e-12 and abs(b-x['rolling_native_median_seconds'])<1e-12;assert abs(a/b-x['native_substep_median_speedup'])<1e-12;assert abs(100*(1-b/a)-x['native_substep_duration_reduction_percent'])<1e-12
for v in results[1:]:assert v['profiles']==results[0]['profiles'] and v['session_state_sha256']==results[0]['session_state_sha256']
di=x['diagnostic_pair'];assert di[0]['profiles']==di[1]['profiles'] and di[0]['session_state_sha256']==di[1]['session_state_sha256'];assert max(new)<min(old)
e={'receipt_sha256':hashlib.sha256(raw.read_bytes()).hexdigest(),'ticks':x['ticks'],'sessions':x['sessions'],'original_native_seconds':old,'rolling_native_seconds':new,'original_median_seconds':a,'rolling_median_seconds':b,'speedup':a/b,'duration_reduction_percent':100*(1-b/a),'production_and_diagnostic_exact':True,'both_rolling_runs_faster_than_both_original_runs':True,'full_pipeline_speedup_measured':False,'comparison_plan':[{'question':'Did rolling percentiles reduce the same native work?','grain':'ABBA_REPEAT_SAME_TAPE_NOT_INDEPENDENT_SESSIONS','population':'470027ticks_4GCsessions_3configs','unit':'NATIVE_PUSH_FINISH_SECONDS','finding':'Both rolling timings below both original timings;1.4767x medians','disposition':'chart','reason':'Show measured repeat variation without including instrumentation/diagnostics'}],'profile_review':{'repeat_number_is_key':'PER_ALGORITHM','same_tape_ticks_not_additive':True,'constant_protocol_metadata_not_missing':True}}
O=Path(args.out);O.mkdir(parents=True,exist_ok=True);(O/'analysis.json').write_text(json.dumps(e,indent=2)+'\n')
with (O/'times.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=['algorithm','order','native_seconds']);w.writeheader();w.writerows({'algorithm':r['algorithm'],'order':i+1,'native_seconds':r['native_push_and_finish_seconds']} for i,r in enumerate(results))
spec={'version':1,'form':'categorical-bars','mode':'grouped','title':'El percentil incremental reduce la duración del subpaso BT2A','aside':'Mismos470.027 ticks/4 sesionesGC; tres perfiles. RepeticionesABBA, no réplicas de mercado. Paridad exacta. Tiempos nativos (s), no pipeline completo.','labels':['Repetición1','Repetición2'],'series':[{'label':'Original','role':'base','valueKind':'number','data':old},{'label':'Percentil incremental','role':'subject','valueKind':'number','data':new}],'axis':{'zero':True}};(O/'chart-spec.json').write_text(json.dumps(spec));print('speedup',e['speedup'],'duration_reduction_percent',e['duration_reduction_percent'])
